    25	        List<Room> allRooms = roomRepository.findAll();
    26	
    27	        StringBuilder csv = new StringBuilder();
    28	        csv.append("room,type,reservation,check_in,check_out\n");
    29	
    30	        for (Reservation reservation : reservations) {
    31	            csv.append(reservation.getRoomNumber()).append(",");
    32	
    33	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
    34	            csv.append(room.getType()).append(",");
    35	            csv.append(reservation.getId()).append(",");
    36	            csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
    37	            csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append("\n");
    38	        }
    39	
    40	        csv.append("total,").append(reservations.size()).append("/").append(allRooms.size());
    41	
    42	        return csv.toString();
    43	    }
    44	
    45	    public String generateRevenueReport(int year, int month) {
    46	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(year, month);
    47	
    48	        StringBuilder csv = new StringBuilder();
    49	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    50	
    51	        BigDecimal totalRevenue = BigDecimal.ZERO;
    52	
    53	        for (Reservation reservation : reservations) {
    54	            BigDecimal revenue = reservation.getAmountPaid();
    55	            if (reservation.getRefund() != null) {
    56	                revenue = revenue.subtract(reservation.getRefund());
    57	            }
    58	
    59	            if (revenue.compareTo(BigDecimal.ZERO) > 0) {
    60	                csv.append(reservation.getId()).append(",");
    61	                csv.append(reservation.getRoomNumber()).append(",");
    62	                csv.append(reservation.getCheckIn().format(DATE_FORMATTER)).append(",");
    63	                csv.append(reservation.getCheckOut().format(DATE_FORMATTER)).append(",");
    64	                csv.append(reservation.getStatus()).append(",");
    65	                csv.append(formatAmount(revenue)).append("\n");
    66	
    67	                totalRevenue = totalRevenue.add(revenue);
    68	            }
    69	        }
    70	
    71	        csv.append("total,").append(formatAmount(totalRevenue));
    72	
    73	        return csv.toString();
    74	    }
