    12	public class ReservationService {
    13	    private final ReservationRepository reservationRepository;
    14	    private final RoomRepository roomRepository;
    15	    private final PricingService pricingService;
    16	    private final MessageService messageService;
    17	
    18	    public ReservationService(ReservationRepository reservationRepository,
    19	                            RoomRepository roomRepository,
    20	                            PricingService pricingService,
    21	                            MessageService messageService) {
    22	        this.reservationRepository = reservationRepository;
    23	        this.roomRepository = roomRepository;
    24	        this.pricingService = pricingService;
    25	        this.messageService = messageService;
    26	    }
    27	
    28	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    29	                                        GuestIdentification identification,
    30	                                        LocalDate checkIn, LocalDate checkOut,
    31	                                        int guests, RatePlan ratePlan) {
    32	        Room room = roomRepository.findByNumber(roomNumber)
    33	            .orElseThrow(() -> new RoomNotFoundException("Room not found: " + roomNumber));
    34	
    35	        if (guests < 1) {
    36	            throw new InvalidRequestException("At least one guest is required");
    37	        }
    38	
    39	        if (guests > room.getCapacity()) {
    40	            throw new CapacityExceededException("Room capacity exceeded");
    41	        }
    42	
    43	        if (!checkOut.isAfter(checkIn)) {
    44	            throw new InvalidRequestException("Check-out must be after check-in");
    45	        }
    46	
    47	        if (!reservationRepository.findConflicting(roomNumber, checkIn, checkOut, null).isEmpty()) {
    48	            throw new RoomUnavailableException("Room is not available for the selected dates");
    49	        }
    50	
    51	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    52	        BigDecimal subtotal = pricingService.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    53	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
