386	    21	        LocalDate current = checkIn;
387	    22	
388	    23	        while (current.isBefore(checkOut)) {
389	    24	            BigDecimal nightPrice = calculateNightPrice(baseRate, current);
390	    25	            subtotal = subtotal.add(nightPrice);
391	    26	            current = current.plusDays(1);
392	    27	        }
393	    28	
394	    29	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
395	    30	    }
