     1	package com.pousadamareal.service;
     2	
     3	import com.pousadamareal.model.RatePlan;
     4	
     5	import java.math.BigDecimal;
     6	import java.math.RoundingMode;
     7	import java.time.LocalDate;
     8	
     9	public class PricingService {
    10	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    11	
    12	    public BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate night) {
    13	        if (isHighSeason(night)) {
    14	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
    15	        }
    16	        return baseRate;
    17	    }
    18	
    19	    public BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    20	        BigDecimal subtotal = BigDecimal.ZERO;
    21	        LocalDate current = checkIn;
    22	
    23	        while (current.isBefore(checkOut)) {
    24	            BigDecimal nightPrice = calculateNightPrice(baseRate, current);
    25	            subtotal = subtotal.add(nightPrice);
    26	            current = current.plusDays(1);
    27	        }
    28	
    29	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
    30	    }
    31	
    32	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    33	        return subtotal.multiply(ratePlan.getDiscountRate()).setScale(2, RoundingMode.HALF_EVEN);
    34	    }
    35	
    36	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    37	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
    38	    }
    39	
    40	    private boolean isHighSeason(LocalDate date) {
    41	        int month = date.getMonthValue();
    42	        int day = date.getDayOfMonth();
    43	
    44	        if (month == 7) {
    45	            return true;
    46	        }
    47	
    48	        if (month == 12 && day >= 15) {
    49	            return true;
    50	        }
    51	
    52	        if (month == 1 || month == 2) {
    53	            return true;
    54	        }
    55	
    56	        return false;
    57	    }
    58	}
