   132	        """ + (excludeId != null ? " AND id != ?" : "");
   133	
   134	        List<Reservation> conflicts = new ArrayList<>();
   135	        try (Connection conn = database.getConnection();
   136	             PreparedStatement stmt = conn.prepareStatement(sql)) {
   137	
