   139	            stmt.setDate(2, Date.valueOf(checkOut));
   140	            stmt.setDate(3, Date.valueOf(checkIn));
   141	            if (excludeId != null) {
   142	                stmt.setLong(4, excludeId);
   143	            }
   144	
   145	            var rs = stmt.executeQuery();
   146	            while (rs.next()) {
   147	                conflicts.add(buildReservation(rs));
   148	            }
   149	        } catch (SQLException e) {
   150	            throw new RuntimeException("Failed to check conflicts", e);
   151	        }
   152	        return conflicts;
