   155	    public List<Reservation> findByCheckInMonth(int year, int month) {
   156	        String sql = """
   157	            SELECT * FROM reservations
   158	            WHERE EXTRACT(YEAR FROM check_in) = ?
   159	            AND EXTRACT(MONTH FROM check_in) = ?
   160	            ORDER BY check_in, id
   161	        """;
   162	
   163	        List<Reservation> reservations = new ArrayList<>();
   164	        try (Connection conn = database.getConnection();
   165	             PreparedStatement stmt = conn.prepareStatement(sql)) {
