   125	    public List<Reservation> findConflicting(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) {
   126	        String sql = """
   127	            SELECT * FROM reservations
   128	            WHERE room_number = ?
   129	            AND status != 'CANCELLED'
   130	            AND check_in < ?
   131	            AND check_out > ?
   132	        """ + (excludeId != null ? " AND id != ?" : "");
   133	
   134	        List<Reservation> conflicts = new ArrayList<>();
   135	        try (Connection conn = database.getConnection();
   136	             PreparedStatement stmt = conn.prepareStatement(sql)) {
   137	
   138	            stmt.setString(1, roomNumber);
   139	            stmt.setDate(2, Date.valueOf(checkOut));
