   180	    public List<Reservation> findByNight(LocalDate night) {
   181	        String sql = """
   182	            SELECT * FROM reservations
   183	            WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
   184	            AND check_in <= ?
   185	            AND check_out > ?
   186	            ORDER BY room_number
   187	        """;
   188	
   189	        List<Reservation> reservations = new ArrayList<>();
   190	        try (Connection conn = database.getConnection();
   191	             PreparedStatement stmt = conn.prepareStatement(sql)) {
   192	
   193	            stmt.setDate(1, Date.valueOf(night));
   194	            stmt.setDate(2, Date.valueOf(night));
   195	
   196	            var rs = stmt.executeQuery();
   197	            while (rs.next()) {
   198	                reservations.add(buildReservation(rs));
   199	            }
   200	        } catch (SQLException e) {
   201	            throw new RuntimeException("Failed to fetch reservations", e);
   202	        }
   203	        return reservations;
   204	    }
   205	
   206	    private Reservation buildReservation(ResultSet rs) throws SQLException {
   207	        GuestIdentification identification;
   208	        String cpf = rs.getString("guest_cpf");
   209	        String cnpj = rs.getString("company_cnpj");
   210	        String passport = rs.getString("guest_passport");
   211	
   212	        if (cpf != null) {
   213	            identification = new CpfIdentification(cpf);
   214	        } else if (cnpj != null) {
   215	            identification = new CnpjIdentification(cnpj, rs.getString("company_name"));
   216	        } else {
   217	            identification = new PassportIdentification(passport, rs.getString("guest_country"));
   218	        }
   219	
   220	        return new Reservation(
   221	            rs.getLong("id"),
   222	            rs.getString("room_number"),
   223	            rs.getString("guest_name"),
   224	            rs.getString("guest_email"),
   225	            identification,
   226	            rs.getDate("check_in").toLocalDate(),
   227	            rs.getDate("check_out").toLocalDate(),
   228	            rs.getInt("guests"),
   229	            RatePlan.valueOf(rs.getString("rate_plan")),
   230	            rs.getInt("nights"),
   231	            rs.getBigDecimal("subtotal"),
   232	            rs.getBigDecimal("discount"),
   233	            rs.getBigDecimal("total"),
   234	            ReservationStatus.valueOf(rs.getString("status")),
   235	            rs.getBigDecimal("amount_paid"),
   236	            rs.getBigDecimal("refund")
   237	        );
   238	    }
   239	}
